    try:
        content = z.read('xl/sharedStrings.xml')
        root = ET.fromstring(content)
        ns = {'': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        strings = [si.text if si.text else '' for si in root.findall('.//t')]
        print('Shared strings count:', len(strings))
    except:
        strings = []

    for sheet_name in ['sheet1.xml', 'sheet2.xml', 'sheet3.xml', 'sheet4.xml', 'sheet5.xml', 'sheet6.xml', 'sheet7.xml', 'sheet8.xml']:
        print(f'\n=== {sheet_name} ===')
