        ns = {'': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        for row in root.findall('.//row'):
            row_data = []
            for c in row.findall('c'):
                if c.get('t') == 's':
                    idx = int(c.find('v').text) if c.find('v') is not None else 0
                    val = strings[idx] if idx < len(strings) else ''
                else:
                    val = c.find('v').text if c.find('v') is not None else ''
                row_data.append(val)
            if any(row_data):
                print(' | '.join(row_data))
