import re

with open('30_drawings/50_bim/BLDG4410-E_RevC.ifc', 'r') as f:
    content = f.read()

# Find all IfcSpace entities
spaces = {}
for match in re.finditer(r'#(\d+)=IFCSPACE\(([^)]*)\)', content):
    num = match.group(1)
    data = match.group(2)
    name_match = re.search(r"'([^']*)'", data)
    if name_match:
        spaces[num] = name_match.group(1)

print('Spaces found:', len(spaces))
for k, v in list(spaces.items()):
    print(f'  #{k}: {v}')

# Find IfcLightFixture entities
light_fixtures = {}
for match in re.finditer(r'#(\d+)=IFCLIGHTFIXTURE\(([^)]*)\)', content):
    num = match.group(1)
    data = match.group(2)
    # Extract type/reference
    type_match = re.search(r"'([^']*)'", data)
    if type_match:
        light_fixtures[num] = type_match.group(1)

print('\nLight fixtures found:', len(light_fixtures))
for k, v in list(light_fixtures.items())[:20]:
