import re

with open('50_bim/BLDG4410-E_RevC.ifc', 'r') as f:
    content = f.read()

lines = content.split('\n')
# Build type map
type_map = {}
for line in lines:
    if 'IFCLIGHTFIXTURETYPE' in line:
        # Parse: #910=IFCLIGHTFIXTURETYPE('id',#6,'desc',$,$,(#909),(#900),'L1','L1',.DIRECTIONSOURCE.);
        match = re.match(r'#(\d+)=IFCLIGHTFIXTURETYPE\([^,]*,[^,]*,[^,]*,[^,]*,[^,]*,\(#(\d+)\),\(#(\d+)\),\'([^\']+)\'', line)
        if match:
            entity_id = match.group(1)
            type_mark = match.group(4)
            type_map[entity_id] = type_mark

print('Type map:')
for k, v in type_map.items():
    print(f'  #{k} -> {v}')

# Now find IfcLightFixture instances
fixture_count = 0
type_counts = {}
space_assignments = {}  # Will need to trace through containment

for line in lines:
    if line.startswith('#') and 'IFCLIGHTFIXTURE(' in line and 'TYPE' not in line:
        # #974=IFCLIGHTFIXTURE('2boRXcOOmwfd5e3m3Ciy4t',#6,'LTG-101-1',$,'L4',#970,#973,'L4',.POINTSOURCE.);
        match = re.match(r'#(\d+)=IFCLIGHTFIXTURE\([^,]*,[^,]*\'([^\']*)\',\$,([^,]*),([^,]*),([^,]*),\'([^\']+)\'', line)
        if match:
            entity_id = match.group(1)
            name = match.group(2)
            type_ref = match.group(3).strip()
            placement_ref = match.group(4).strip()
            type_mark = match.group(5)

            # Resolve type
            if type_ref.startswith('#'):
                ref_id = type_ref[1:]
                actual_type = type_map.get(ref_id, type_mark)
            else:
                actual_type = type_mark

            type_counts[actual_type] = type_counts.get(actual_type, 0) + 1
            fixture_count += 1

print(f'\nTotal fixtures: {fixture_count}')
print('Counts by type:')
for t, c in sorted(type_counts.items()):
    print(f'  {t}: {c}')
"

