import zipfile
import xml.etree.ElementTree as ET

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

for spec in ['26_05_73', '26_20_00', '26_24_13', '26_32_15', '26_36_23', '26_51_00']:
    with zipfile.ZipFile(f'output/specs/{spec}.docx', 'r') as z:
        doc_xml = z.read('word/document.xml')
    root = ET.fromstring(doc_xml)
    paras = []
    for p in root.findall('.//w:p', ns):
        texts = []
        for t in p.findall('.//w:t', ns):
            if t.text:
                texts.append(t.text)
        if texts:
            paras.append(''.join(texts))
    print(f'=== {spec}.docx ===')
    for i, para in enumerate(paras[:5]):
        print(f'  {para}')
    print(f'  ... ({len(paras)} paragraphs total)')
    # Check last few
    for para in paras[-3:]:
        print(f'  {para}')
    print()
"

